    # Final derivative-free pattern-direct-search polish of the incumbent.
    # SLSQP terminates on its merit-function criterion with KKT residual
    # left in near-active edges, and its steps are confined to the
    # linearized active-constraint nullspace. Powell's conjugate direction
    # sets and COBYLA's linear trust region are unconstrained by that
    # geometry and can cross the tiny barriers that stall SLSQP. Bounded:
    # <= 2 Powell-style runs (maxfev 4000 / 2000) + 1 COBYLA run
    # (maxiter 1500), each re-normalizing dmax = 1 inside the objective.
    # Strictly guarded by the exact ratio, so the incumbent only improves.
    if bestP is not None:
        def _direct_polish(P0):
            from scipy.optimize import minimize
            P = np.asarray(P0, dtype=float).copy()
            bP, bR = P.copy(), _ratio(P)

            def _norm(Q):
                d2 = ((Q[:, None, :] - Q[None, :, :]) ** 2).sum(-1)
                dmx = float(np.sqrt(d2[np.triu_indices(len(Q), 1)].max()))
                return Q / dmx if dmx > 1e-12 else Q

            def _obj(x):
                return -_ratio(_norm(x.reshape(-1, 3)))

            for meth, opts in (("Powell",
                                {"maxfev": 4000, "xtol": 1e-10,
                                 "ftol": 1e-12}),
                               ("Powell",
                                {"maxfev": 2000, "xtol": 1e-12,
                                 "ftol": 1e-14})):
                try:
                    res = minimize(_obj, _norm(bP).ravel(),
                                   method=meth, options=opts)
                    Q = res.x.reshape(-1, 3)
                    if np.all(np.isfinite(Q)):
                        r = _ratio(Q)
                        if r > bR:
                            bR, bP = r, Q.copy()
                except Exception:
                    pass

            def _obj_cob(x):
                Q = x.reshape(-1, 3)
                d2 = ((Q[:, None, :] - Q[None, :, :]) ** 2).sum(-1)
                d = d2[np.triu_indices(len(Q), 1)]
                pen = 1e3 * max(0.0, float(d.max()) - 1.0)
                return -(float(d.min()) - pen)

            try:
                res = minimize(_obj_cob, _norm(bP).ravel(),
                               method="COBYLA",
                               options={"maxiter": 1500, "rhobeg": 0.05,
                                        "tol": 1e-10})
                Q = res.x.reshape(-1, 3)
                if np.all(np.isfinite(Q)):
                    r = _ratio(Q)
                    if r > bR:
                        bR, bP = r, Q.copy()
            except Exception:
                pass
            return bP

        try:
            _consider(_direct_polish(bestP.copy()))
        except Exception:
            pass
        try:
            _consider(_kkt_refine(bestP.copy()))
        except Exception:
